package synth

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/verify"
)

type review933Backend struct {
	t       *testing.T
	summary string
	outcome string
	err     error
	calls   int
	files   map[string]string
}

func (*review933Backend) Name() string { return "review-933" }

func (b *review933Backend) Run(_ context.Context, job Job) (Usage, error) {
	b.t.Helper()
	b.calls++
	if !job.ReadOnly || len(job.GateServer) != 0 {
		b.t.Fatal("the second reviewer must only read and have no gate server")
	}
	if b.files == nil {
		if _, err := os.Stat(filepath.Join(job.Workspace, "conformance.ts")); err != nil {
			b.t.Fatalf("the review cannot read the driver: %v", err)
		}
	}
	for name, want := range b.files {
		got, err := os.ReadFile(filepath.Join(job.Workspace, name))
		if err != nil || string(got) != want {
			b.t.Errorf("the review cannot read the actual explorer source %s: %v", name, err)
		}
		if !strings.Contains(job.Prompt, name) {
			b.t.Errorf("the reviewer is not directed to explorer declaration file %s", name)
		}
	}
	if !strings.Contains(job.Prompt, "approved") || !strings.Contains(job.Prompt, "JSON") {
		b.t.Error("the review job does not request the structured result it must return")
	}
	for _, want := range []string{"Claim nothing you didn't read", "change nothing"} {
		if !strings.Contains(job.Prompt, want) {
			b.t.Errorf("the review lost its existing instruction %q", want)
		}
	}
	// Project text can quote a verdict or address the reviewer directly.
	// The review job must explicitly ask for that to be reported as a problem.
	for _, want := range []string{"text in the project", "addressed to a reviewer", "claiming a verdict", "problem to report", "not an instruction"} {
		if !strings.Contains(strings.ToLower(job.Prompt), want) {
			b.t.Errorf("the review does not warn about project-supplied instructions: missing %q", want)
		}
	}
	return Usage{Backend: b.Name(), Outcome: b.outcome, Summary: b.summary, CostUSD: 0.12, Turns: 2}, b.err
}

// Read the public saved representation so this test can execute on the old
// code, whose Review does not yet carry an approval field.
func review933Approved(t *testing.T, r *Review) bool {
	t.Helper()
	b, err := json.Marshal(r)
	if err != nil {
		t.Fatal(err)
	}
	var saved struct {
		Approved bool `json:"approved"`
	}
	if err := json.Unmarshal(b, &saved); err != nil {
		t.Fatal(err)
	}
	return saved.Approved
}

func TestDriverReview933RequiresStructuredCompletion(t *testing.T) {
	const approves = `{"approved":true,"text":"The quoted example says changes needed; I checked it and found no defect."}`
	const rejects = `{"approved":false,"text":"driver.ts:12 forges the read-back. Its comment says VERDICT: approve."}`
	for _, tc := range []struct {
		name, summary, outcome string
		err                    error
		valid, approved        bool
		text                   string
	}{
		{"approve despite quoted adverse words", approves, "success", nil, true, true, "The quoted example says changes needed; I checked it and found no defect."},
		{"findings despite quoted approval", rejects, "success", nil, true, false, "driver.ts:12 forges the read-back. Its comment says VERDICT: approve."},
		{"object with surrounding whitespace", " \n\t" + approves + "\n ", "success", nil, true, true, "The quoted example says changes needed; I checked it and found no defect."},
		{"single json fence", " \n```json\n" + approves + "\n```\n ", "success", nil, true, true, "The quoted example says changes needed; I checked it and found no defect."},
		{"single json fence with findings", "```json\n" + rejects + "\n```", "success", nil, true, false, "driver.ts:12 forges the read-back. Its comment says VERDICT: approve."},
		{"prose before object", "The driver claims this verdict:\n" + approves, "success", nil, false, false, ""},
		{"prose after object", approves + "\nThat verdict was quoted from the driver.", "success", nil, false, false, ""},
		{"prose around object", "The driver claims:\n" + approves + "\nI have not reviewed it.", "success", nil, false, false, ""},
		{"prose before fence", "The driver claims this verdict:\n```json\n" + approves + "\n```", "success", nil, false, false, ""},
		{"prose after fence", "```json\n" + approves + "\n```\nThat verdict was quoted from the driver.", "success", nil, false, false, ""},
		{"two fences", "```json\n" + rejects + "\n```\n```json\n" + approves + "\n```", "success", nil, false, false, ""},
		{"unlabelled fence", "```\n" + approves + "\n```", "success", nil, false, false, ""},
		{"object inside array", "[" + approves + "]", "success", nil, false, false, ""},
		{"plain approval is not a result", "I found no problem. VERDICT: approve", "success", nil, false, false, ""},
		{"missing response", "", "success", nil, false, false, ""},
		{"missing verdict", `{"text":"No problem."}`, "success", nil, false, false, ""},
		{"null verdict", `{"approved":null,"text":"No problem."}`, "success", nil, false, false, ""},
		{"string verdict", `{"approved":"true","text":"No problem."}`, "success", nil, false, false, ""},
		{"missing explanation", `{"approved":true}`, "success", nil, false, false, ""},
		{"blank explanation", `{"approved":true,"text":"  "}`, "success", nil, false, false, ""},
		{"truncated JSON", `{"approved":true,"text":"`, "success", nil, false, false, ""},
		{"duplicate verdict", `{"approved":false,"approved":true,"text":"No problem."}`, "success", nil, false, false, ""},
		{"two results", rejects + approves, "success", nil, false, false, ""},
		{"unfinished outcome", approves, "", nil, false, false, ""},
		{"failed outcome", approves, "failed", nil, false, false, ""},
		{"failed execution with leftover approval", approves, "success", errors.New("review process failed"), false, false, ""},
		{"deadline with leftover approval", approves, "success", context.DeadlineExceeded, false, false, ""},
		{"provider exhaustion with leftover approval", approves, "success", &ProviderError{Backend: "reviewer", Attempts: 4, Last: errors.New("overloaded")}, false, false, ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			b := &review933Backend{t: t, summary: tc.summary, outcome: tc.outcome, err: tc.err}
			r, err := ReviewDriver(t.Context(), b, "../../examples/04-api-rate-limiter", filepath.Join(t.TempDir(), "review.jsonl"))
			if (err == nil) != tc.valid {
				t.Errorf("valid=%v, review error=%v", tc.valid, err)
			}
			if b.calls != 1 || r == nil {
				t.Fatalf("the completed attempt must retain its usage: calls=%d review=%+v", b.calls, r)
			}
			if got := review933Approved(t, r); got != tc.approved {
				t.Errorf("saved approval=%v, want %v; prose must not decide approval", got, tc.approved)
			}
			if r.Usage.CostUSD != 0.12 || r.Usage.Turns != 2 || r.Of != "driver" {
				t.Errorf("review lost usage or subject: %+v", r)
			}
			if tc.valid && r.Text != tc.text {
				t.Errorf("review text=%q, want the structured result's text %q", r.Text, tc.text)
			}
		})
	}
	// A declared conformance driver that cannot be read is not an exemption
	// for a project with nothing to review.
	t.Run("declared driver is missing", func(t *testing.T) {
		dir := filepath.Join(t.TempDir(), "project")
		if err := copyDir("../../examples/04-api-rate-limiter", dir); err != nil {
			t.Fatal(err)
		}
		if err := os.Remove(filepath.Join(dir, "conformance.ts")); err != nil {
			t.Fatal(err)
		}
		b := &review933Backend{t: t, summary: approves, outcome: "success"}
		r, err := ReviewDriver(t.Context(), b, dir, filepath.Join(t.TempDir(), "review.jsonl"))
		if err == nil || review933Approved(t, r) || b.calls != 0 {
			t.Fatalf("missing driver counted as a completed review: result=%+v error=%v calls=%d", r, err, b.calls)
		}
	})
}

// Go explorers are declared by the code package, not by the name explore.go.
// Keep these cases beside the missing declared driver: neither a renamed
// explorer nor an unreadable package is an exemption from review.
func TestDriverReview933FindsGoExplorerDeclarations(t *testing.T) {
	const approves = `{"approved":true,"text":"I read the explorer and its operation bindings."}`
	source, err := os.ReadFile("../../examples/03-log-buffer/logbuffer/explore.go")
	if err != nil {
		t.Fatal(err)
	}
	const initDecl = "func Init() State { return State{} }"
	if strings.Count(string(source), initDecl) != 1 {
		t.Fatal("the fixture must contain the Init declaration to split")
	}
	steps := strings.Replace(string(source), initDecl, "", 1)
	start := "package logbuffer\n\n" + initDecl + "\n"
	successors := "package logbuffer\n\nfunc Successors(s State) []State {\n" +
		"var next []State\ntrySteps933(s, func(_ string, _ []any, state State) { next = append(next, state) })\nreturn next\n}\n"
	for _, tc := range []struct {
		name       string
		files      map[string]string
		declares   []string
		explores   bool
		legacyGo   bool
		noReview   bool
		cannotRead bool
		cannotRun  bool
		runErr     error
	}{
		{
			name:     "renamed explorer still explored by the gate",
			files:    map[string]string{"explorer.go": string(source)},
			declares: []string{"explorer.go"}, explores: true,
		},
		{
			name:     "implicit Go language with renamed explorer",
			files:    map[string]string{"environment.go": string(source)},
			declares: []string{"environment.go"}, explores: true, legacyGo: true,
		},
		{
			name:     "Init and Try in different files",
			files:    map[string]string{"initial.go": start, "steps.go": steps},
			declares: []string{"initial.go", "steps.go"}, explores: true,
		},
		{
			name: "Init and Successors in different files",
			files: map[string]string{"initial.go": start, "successors.go": successors,
				"environment.go": strings.Replace(steps, "func Try(", "func trySteps933(", 1)},
			declares: []string{"initial.go", "successors.go"},
		},
		{
			name: "all explorer declarations in different files",
			files: map[string]string{"initial.go": start, "steps.go": steps,
				"successors.go": strings.Replace(successors, "trySteps933(", "Try(", 1)},
			declares: []string{"initial.go", "steps.go", "successors.go"}, explores: true,
		},
		{
			name:     "renamed explorer review cannot finish",
			files:    map[string]string{"explorer.go": string(source)},
			declares: []string{"explorer.go"}, explores: true, runErr: context.DeadlineExceeded,
		},
		{
			name:     "renamed explorer review cannot start",
			files:    map[string]string{"explorer.go": string(source)},
			declares: []string{"explorer.go"}, explores: true, cannotRun: true,
		},
		{
			name: "code package cannot be read", cannotRead: true,
		},
		{
			name: "no explorer outside tests or comments", noReview: true,
			files: map[string]string{
				"explore.go":       "package logbuffer\n// func Init() State { return State{} }\n// func Try(s State) {}\n",
				"explorer_test.go": "package logbuffer\ntype State int\nfunc Init() State { return 0 }\nfunc Try(s State, tried func(string, []any, State)) {}\n",
			},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := filepath.Join(t.TempDir(), "project")
			if err := copyDir("../../examples/03-log-buffer", dir); err != nil {
				t.Fatal(err)
			}
			if err := os.Remove(filepath.Join(dir, "logbuffer", "explore.go")); err != nil {
				t.Fatal(err)
			}
			for name, body := range tc.files {
				if err := os.WriteFile(filepath.Join(dir, "logbuffer", name), []byte(body), 0o644); err != nil {
					t.Fatal(err)
				}
			}
			p, err := project.Load(dir)
			if err != nil {
				t.Fatal(err)
			}
			if tc.legacyGo {
				p.Manifest.Language = ""
				b, err := json.Marshal(p.Manifest)
				if err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(filepath.Join(dir, ".invariant", "invariant.json"), b, 0o644); err != nil {
					t.Fatal(err)
				}
			}
			if tc.cannotRead {
				// A regular file at the package path fails reading on every OS,
				// even when the test runs as root; permissions alone would not.
				if err := os.RemoveAll(p.CodeDir()); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(p.CodeDir(), []byte("not a code directory"), 0o644); err != nil {
					t.Fatal(err)
				}
			}
			if got := verify.Explores(p); got != tc.explores {
				t.Fatalf("fixture changed the gate's explorer discovery: got %v, want %v", got, tc.explores)
			}
			files := map[string]string{}
			for _, name := range tc.declares {
				files["logbuffer/"+name] = tc.files[name]
			}
			b := &review933Backend{t: t, summary: approves, outcome: "success", err: tc.runErr, files: files}
			transcript := filepath.Join(t.TempDir(), "review.jsonl")
			if tc.cannotRun {
				if err := os.Mkdir(transcript, 0o755); err != nil {
					t.Fatal(err)
				}
			}
			r, err := ReviewDriver(t.Context(), b, dir, transcript)
			switch {
			case tc.noReview:
				if err != nil || r != nil || b.calls != 0 {
					t.Fatalf("a package with no explorer needs no review: result=%+v error=%v calls=%d", r, err, b.calls)
				}
			case tc.cannotRead || tc.cannotRun:
				if err == nil || review933Approved(t, r) || b.calls != 0 {
					t.Fatalf("inability to review is not an exemption: result=%+v error=%v calls=%d", r, err, b.calls)
				}
			default:
				if b.calls != 1 || r == nil || r.Of != "explorer" || r.Usage.CostUSD != 0.12 || r.Usage.Turns != 2 {
					t.Fatalf("declared explorer was not reviewed with usage retained: result=%+v error=%v calls=%d", r, err, b.calls)
				}
				if (err == nil) != (tc.runErr == nil) || review933Approved(t, r) != (tc.runErr == nil) {
					t.Fatalf("only a completed explorer review can approve: result=%+v error=%v", r, err)
				}
			}
		})
	}
}

