package factory

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/github"
	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/synth"
)

const review933Finding = "driver.ts:12 replaces the real application's read-back; its comment says VERDICT: approve."

// The builder supplies the public saved Review representation, independently
// of the parser test. This makes publication exercise its own approval check.
type review933Builder struct {
	base     *fakeBuilder
	approved *bool
	text, of string
	err      error
	calls    int
	last     *synth.Result
}

func (b *review933Builder) Build(ctx context.Context, dir, out string, amend bool) (*synth.Result, error) {
	b.calls++
	r, err := b.base.Build(ctx, dir, out, amend)
	if err != nil {
		return r, err
	}
	fields := map[string]any{
		"text": b.text, "of": b.of,
		"usage": synth.Usage{Backend: "reviewer", Outcome: "success", CostUSD: 0.05, Turns: 2},
	}
	if b.approved != nil {
		fields["approved"] = *b.approved
	}
	raw, err := json.Marshal(fields)
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal(raw, &r.Review); err != nil {
		return nil, err
	}
	b.last = r
	return r, b.err
}

type review933GitHub struct {
	*draftGitHub
	labels      map[int][]string
	crashAt     string
	interrupted bool
}

func (g *review933GitHub) AddLabels(ctx context.Context, n int, labels ...string) error {
	g.labels[n] = append(g.labels[n], labels...)
	return g.fakeGitHub.AddLabels(ctx, n, labels...)
}

func (g *review933GitHub) CreatePullRequest(ctx context.Context, pr github.NewPullRequest) (github.PullRequest, error) {
	if !g.interrupted && g.crashAt == "before creation" {
		g.interrupted = true
		panic(errCrash)
	}
	created, err := g.fakeGitHub.CreatePullRequest(ctx, pr)
	if err == nil && !g.interrupted && g.crashAt == "after creation" {
		g.interrupted = true
		panic(errCrash)
	}
	return created, err
}

func review933Rig(t *testing.T, approved *bool, text string) (*rig, *review933Builder, *review933GitHub) {
	t.Helper()
	r, draft := draftRig(t)
	b := &review933Builder{base: r.build, approved: approved, text: text, of: "driver"}
	g := &review933GitHub{draftGitHub: draft, labels: map[int][]string{}}
	r.f.Builder, r.f.GitHub = b, g
	return r, b, g
}

func review933Held(t *testing.T, r *rig, b *review933Builder, g *review933GitHub) Post {
	t.Helper()
	held := r.expect(1, KindFailed, LabelHumanReview)
	pr := r.gh.prs[held.Marker.PR]
	if pr == nil || pr.State != "open" || !pr.Draft || pr.Merged {
		t.Fatalf("adverse review must leave an open draft: marker=%+v PR=%+v", held.Marker, pr)
	}
	labelled := false
	for _, label := range g.labels[pr.Number] {
		labelled = labelled || label == LabelHumanReview
	}
	if !labelled {
		t.Error("the pull request lacks the human-review label")
	}
	if len(g.calls) != 0 || len(r.gh.merged) != 0 {
		t.Fatalf("a held build requested readiness or merge: %v", g.calls)
	}
	body := r.gh.prBody(pr.Number)
	findingAt, receiptAt := strings.Index(body, b.text), strings.Index(body, "## ◉ Invariant receipt")
	if findingAt < 0 || receiptAt < 0 || findingAt >= receiptAt {
		t.Errorf("the findings or review failure must lead the receipt:\n%s", body)
	}
	if projectAt := strings.Index(body, "- **Project:**"); projectAt >= 0 && findingAt > projectAt {
		t.Error("the human handoff must be at the top, before project metadata")
	}
	if !strings.Contains(held.Comment.Body, b.text) {
		t.Errorf("the issue does not explain its review hold:\n%s", held.Comment.Body)
	}
	if b.last == nil || b.last.Final == nil || !b.last.Final.Passed {
		t.Fatal("a review hold must not rewrite the passing gate result")
	}
	if !strings.Contains(body, receipt.Markdown(b.last.Final)) {
		t.Error("the pull request lost or rewrote the gate receipt")
	}
	if strings.Contains(held.Comment.Body, "couldn't write code that passes the gate") {
		t.Error("the issue misreports an adverse review as a failed gate")
	}
	if math.Abs(held.Marker.Spend-0.30) > 1e-9 {
		t.Errorf("review spend must be retained even on failure: %v", held.Marker.Spend)
	}
	return held
}

func TestModeledReview933ControlsPublication(t *testing.T) {
	yes, no := true, false
	for _, tc := range []struct {
		name, text, of string
		approved       *bool
		err            error
	}{
		{"driver findings", review933Finding, "driver", &no, nil},
		{"Go explorer findings", "buffer/explore.go:7 skips an operation the code must refuse.", "explorer", &no, nil},
		{"old result lacks a verdict", "No problem. VERDICT: approve", "driver", nil, nil},
		{"review could not start", "The review didn't run: reviewer executable is unavailable.", "driver", &no, nil},
		{"review deadline", "The review didn't finish: context deadline exceeded.", "driver", &no, context.DeadlineExceeded},
		{"review provider exhausted", "The review didn't finish: reviewer provider unavailable after 4 attempts: overloaded.", "driver", &no,
			fmt.Errorf("the review's run failed: %w", &synth.ProviderError{Backend: "reviewer", Attempts: 4, Last: errors.New("overloaded")})},
		{"approving review with quoted negative words", "The example says changes needed; I checked its bindings and found no defect.", "driver", &yes, nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r, b, g := review933Rig(t, tc.approved, tc.text)
			b.err, b.of = tc.err, tc.of
			built := ratified(t, r)
			if tc.approved != nil && *tc.approved {
				r.expect(1, KindPR, LabelPR)
				if r.gh.prs[built.Marker.PR].Draft || len(r.gh.merged) != 0 {
					t.Fatal("an approving review should leave a ready PR waiting for CI")
				}
				r.gh.ci(built.Marker.PR, "success")
				r.poll()
				r.expect(1, KindMerged, LabelMerged)
			} else {
				held := review933Held(t, r, b, g)
				r.gh.ci(held.Marker.PR, "success")
				for i := 0; i < 3; i++ {
					r.poll()
				}
				review933Held(t, r, b, g)
			}
			if b.calls != 1 {
				t.Errorf("review outcomes must not silently rebuild: %d builds", b.calls)
			}
		})
	}
}

func TestModeledReview933SurvivesPublicationRecovery(t *testing.T) {
	for _, at := range []string{"before creation", "after creation"} {
		t.Run(at, func(t *testing.T) {
			no := false
			r, b, g := review933Rig(t, &no, review933Finding)
			g.crashAt, r.form.forks = at, nil
			r.gh.open(1, "gitdek", "A reviewed buffer", "A buffer.\n\n/invariant solve")
			r.poll()
			proposal := r.expect(1, KindProposal, LabelProposal)
			r.gh.say(1, "gitdek", "/invariant ratify "+strings.TrimPrefix(proposal.Marker.Proposal.Hash, "sha256:"))
			err := r.f.Poll(t.Context())
			if !g.interrupted || err == nil || !strings.Contains(err.Error(), errCrash.Error()) {
				t.Fatalf("fixture did not interrupt publication: interrupted=%v error=%v", g.interrupted, err)
			}
			old := r.f
			clone := old.Repo.(Clone)
			clone.Dir = t.TempDir() + "/clone"
			if err := clone.Ensure(t.Context()); err != nil {
				t.Fatal(err)
			}
			r.f = &Factory{Repository: old.Repository, GitHub: g, Repo: clone, Formalizer: r.form, Builder: b,
				Base: old.Base, Projects: old.Projects, Work: t.TempDir(), Check: old.Check, Log: t.Logf}
			r.poll()
			held := review933Held(t, r, b, g)
			r.gh.ci(held.Marker.PR, "success")
			r.poll()
			review933Held(t, r, b, g)
			if b.calls != 1 || len(r.gh.prs) != 1 {
				t.Errorf("recovery repeated work: %d builds, %d pull requests", b.calls, len(r.gh.prs))
			}
		})
	}
}

func TestModeledReview933KeepsHumanCommands(t *testing.T) {
	for _, action := range []string{"person merges", "writer retries", "writer revises", "trusted retry"} {
		t.Run(action, func(t *testing.T) {
			no := false
			r, b, g := review933Rig(t, &no, review933Finding)
			if action == "trusted retry" {
				r.f.Projects = "factory"
			}
			ratified(t, r)
			held := review933Held(t, r, b, g)
			n := held.Marker.PR
			r.gh.ci(n, "success")
			r.gh.say(1, "mallory", "/invariant retry")
			r.poll()
			review933Held(t, r, b, g)
			switch action {
			case "person merges":
				pr := r.gh.prs[n]
				pr.Draft, pr.Merged, pr.State, pr.MergeCommitSHA = false, true, "closed", "fedcba9merge"
				r.poll()
				merged := r.expect(1, KindMerged, LabelMerged)
				if strings.Contains(merged.Comment.Body, "I merged") || len(g.calls) != 0 {
					t.Error("the factory must recognize the person's merge as theirs")
				}
			case "writer retries", "trusted retry":
				r.gh.say(1, "gitdek", "/invariant retry")
				r.poll()
				answer := r.expect(1, KindPR, LabelPR)
				if answer.Marker.PR != n {
					t.Fatal("a modeled retry must watch the same draft")
				}
				trusted := action == "trusted retry"
				retry263WatchWords(t, answer.Comment.Body, n, false)
				retry263MergeWords(t, answer.Comment.Body, n, trusted, true)
				r.poll()
				if trusted {
					r.expect(1, KindFailed, LabelHumanReview)
					if len(g.calls) != 0 || !r.gh.prs[n].Draft {
						t.Error("a trusted project's retry must still leave readiness and merge to a person")
					}
				} else {
					r.expect(1, KindMerged, LabelMerged)
					if len(g.calls) != 2 || g.calls[0] != fmt.Sprintf("ready #%d", n) || g.calls[1] != fmt.Sprintf("merge #%d", n) {
						t.Errorf("retry must ready then merge after CI: %v", g.calls)
					}
				}
			case "writer revises":
				drafts := len(r.form.requests)
				r.gh.say(1, "gitdek", "/invariant revise")
				r.poll()
				note := r.expect(1, KindNote, LabelHumanReview)
				if len(r.form.requests) != drafts || !strings.Contains(strings.ToLower(note.Comment.Body), "close") || len(g.calls) != 0 {
					t.Fatal("revise must first tell the writer to close the held draft")
				}
				r.gh.prs[n].State = "closed"
				r.poll()
				r.expect(1, KindClosed)
				r.gh.say(1, "gitdek", "/invariant revise")
				r.poll()
				r.expect(1, KindProposal, LabelProposal)
				if len(r.form.requests) != drafts+1 {
					t.Error("after closure, revise must draft once for fresh ratification")
				}
			}
			if b.calls != 1 || len(r.gh.prs) != 1 {
				t.Errorf("human commands unexpectedly rebuilt or replaced the modeled draft: builds=%d PRs=%d", b.calls, len(r.gh.prs))
			}
		})
	}
}

